css:
:root{--k:#080808;--k2:#111111;--w:#F7F7F5;--g:#F3F4F6;--l:#C7FF3F;--ink:#1a1a1a;--mute:#5f6368;--line:#e2e3e0;--dline:#26262a;--dmute:#a1a1a6;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px);color-scheme:light}
html{scroll-behavior:smooth;scroll-padding-top:80px}
*,*::before,*::after{box-sizing:inherit}
body{margin:0;font:400 16px/1.6 Inter,system-ui,sans-serif;color:var(--ink);background:var(--w);-webkit-font-smoothing:antialiased}
h1,h2,h3,h4{font-family:Sora,Manrope,sans-serif;margin:0;line-height:1.12;letter-spacing:-.02em}
p{margin:0}a{color:inherit;text-decoration:none}
:focus-visible{outline:2px solid var(--l);outline-offset:3px;box-shadow:0 0 0 4px var(--k)}
.wrap{max-width:1200px;margin:0 auto;padding:0 24px}
section{padding:88px 0}
.dark{background:var(--k);color:#fff}.dark2{background:var(--k2);color:#fff}.grey{background:var(--g)}
.dark p,.dark2 p{color:var(--dmute)}
.sh{max-width:640px;margin-bottom:44px}
.sh h2{font-size:clamp(28px,4vw,42px)}
.sh p{margin-top:14px;color:var(--mute);font-size:17px}
.dark .sh p,.dark2 .sh p{color:var(--dmute)}
.btn{display:inline-flex;align-items:center;gap:8px;padding:14px 22px;border-radius:999px;font:600 15px Inter;border:1.5px solid transparent;cursor:pointer;transition:transform .15s,background .15s}
.btn:hover{transform:translateY(-2px)}
.b-l{background:var(--l);color:var(--k)}
.b-o{border-color:#ffffff40;color:#fff}.b-o:hover{background:#ffffff14}
.b-d{background:var(--k);color:#fff}
.ctas{display:flex;flex-wrap:wrap;gap:12px}
.fine{margin-top:22px;font-size:14px;color:var(--mute)}
nav{position:sticky;top:0;z-index:20;background:#080808f2;color:#fff;border-bottom:1px solid var(--dline)}
nav .wrap{display:flex;align-items:center;justify-content:space-between;height:68px}
.logo{font:700 21px Sora;letter-spacing:-.03em}.logo i{font-style:normal;color:var(--l)}
nav ul{display:flex;gap:30px;list-style:none;margin:0;padding:0;font-size:14.5px;color:#d0d0d4}
nav ul a:hover,nav ul a.on{color:var(--l)}
nav .btn{padding:10px 18px;font-size:14px}
/* hero */
.hero{padding:72px 0 88px}
.hero .wrap{display:grid;grid-template-columns:1.05fr 1fr;gap:48px;align-items:center}
.lab{display:inline-flex;align-items:center;gap:10px;font:600 13px Inter;letter-spacing:.08em;color:var(--l);margin-bottom:22px}
.lab::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--l)}
.hero h1{font-size:clamp(34px,4.7vw,60px);line-height:1.04;letter-spacing:-.037em}
.hero .sub{margin:22px 0 32px;font-size:clamp(17px,2vw,19px);max-width:500px;color:#d6d6da}
.hub{position:relative;display:grid;grid-template-columns:1fr 1fr;gap:16px}
.hub::before,.hub::after{content:"";position:absolute;background:var(--l);opacity:.45}
.hub::before{left:0;right:0;top:50%;height:2px}.hub::after{top:0;bottom:0;left:50%;width:2px}
.hub .t{position:relative;z-index:1;background:var(--k2);border:1px solid var(--dline);border-radius:16px;padding:24px 22px}
.hub h4{font-size:16px;color:#fff;margin-bottom:6px}.hub .t p{font-size:13.5px}
.core{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);z-index:2;background:var(--l);color:var(--k);font:700 14px Sora;padding:12px 20px;border-radius:99px;box-shadow:0 0 0 8px var(--k);white-space:nowrap}
/* industry cards */
.cards{display:grid;grid-template-columns:repeat(2,1fr);gap:22px}
.ic{background:#fff;border:1px solid var(--line);border-radius:24px;padding:14px;display:flex;flex-direction:column;transition:border-color .2s}
.ic:hover{border-color:var(--k)}
.mk{background:var(--k);border-radius:16px;height:176px;padding:18px;display:flex;flex-direction:column;gap:8px;overflow:hidden;position:relative}
.ic .bd{padding:22px 12px 12px;display:flex;flex-direction:column;flex:1}
.ic h3{font-size:22px;margin-bottom:10px}
.ic .ch{font-size:15px;color:var(--mute);margin-bottom:16px}
.ic .ch b{color:var(--ink);font-weight:600}
.sv{list-style:none;margin:0 0 12px;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.sv li{font-size:12.5px;font-weight:500;padding:5px 12px;border-radius:99px;background:var(--g);display:flex;align-items:center;gap:7px}
.sv li::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--k)}
.ic .inc{font-size:14px;color:var(--mute);margin-bottom:20px}
.ic .ex{margin-top:auto;font-weight:600;font-size:15px;display:inline-flex;gap:6px;align-self:flex-start;border-bottom:2px solid var(--l);padding-bottom:2px}
/* mock primitives */
.l{height:7px;border-radius:4px;background:#2a2a2e}.l.w{height:12px;background:#e9e9ea;width:60%}.l.s{width:55%}
.bk{border-radius:10px;background:linear-gradient(135deg,#2a2a2e,#17171a);border:1px solid #333}
.pl{display:inline-block;padding:6px 13px;border-radius:99px;background:var(--l);color:var(--k);font:600 11px Inter;white-space:nowrap}
.rw{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:9px 11px;border-radius:10px;background:#17171a;border:1px solid var(--dline);font-size:11.5px;color:#ddd}
.rw.on{border-color:var(--l)}
.g3{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.g4{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;align-items:center}.g2{display:grid;grid-template-columns:1fr 1fr;gap:10px;flex:1}
.fd{padding:8px 9px;border-radius:8px;background:#17171a;border:1px solid var(--dline);font-size:10.5px;color:var(--dmute)}
.tb{display:flex;gap:6px}.tb i{font-style:normal;font-size:11px;padding:4px 11px;border-radius:99px;background:#1b1b1f;color:var(--dmute)}.tb i.on{background:var(--l);color:var(--k);font-weight:600}
.dy{display:grid;grid-template-columns:repeat(7,1fr);gap:6px}.dy i{aspect-ratio:1;border-radius:7px;background:#1b1b1f}.dy i.on{background:var(--l)}
.ph{width:52px;border:2px solid #34343a;border-radius:12px;background:#17171a;padding:8px 6px;display:flex;flex-direction:column;gap:6px}
/* framework */
.fw{display:grid;grid-template-columns:1fr auto 1fr auto 1fr;gap:14px;align-items:stretch}
.fc{border:1px solid var(--dline);border-radius:20px;padding:30px;background:var(--k2);display:flex;flex-direction:column}
.fc h3{font-size:28px;color:var(--l);margin-bottom:12px}.fc p{margin-bottom:18px}
.fc ul{list-style:none;margin:auto 0 0;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.fc li{font-size:13px;padding:5px 12px;border-radius:99px;background:#1c1c20;border:1px solid var(--dline);color:#e0e0e4}
.arr{align-self:center;color:var(--l);font:600 26px Sora}
/* connected journey */
.flow{display:flex;gap:18px;padding:26px;border-radius:22px;background:var(--k2);border:1px solid var(--dline)}
.nd{flex:1;min-width:0;position:relative;background:var(--k);border:1px solid var(--dline);border-radius:14px;padding:16px 14px}
.nd small{display:block;font:600 11.5px Inter;color:var(--l);margin-bottom:8px}
.nd b{display:block;font:600 14.5px Sora;color:#fff}.nd span{display:block;font-size:12.5px;color:var(--dmute);margin-top:5px;line-height:1.4}
.nd::after{content:"";position:absolute;left:100%;top:50%;width:18px;height:2px;background:var(--l);opacity:.5}
.nd:last-child::after{display:none}
/* process */
.jr{display:grid;grid-template-columns:repeat(5,1fr);counter-reset:s}
.st{padding:0 14px 0 0;position:relative;counter-increment:s}
.st .dot{width:38px;height:38px;border-radius:50%;background:var(--k2);border:2px solid var(--dline);display:grid;place-items:center;margin-bottom:16px;position:relative;z-index:1;font:600 13px Sora;color:var(--l)}
.st .dot::before{content:counter(s)}
.st::after{content:"";position:absolute;left:46px;right:6px;top:18px;height:2px;background:linear-gradient(90deg,var(--l),#2a2a2e)}
.st:last-child::after{display:none}
.st h4{font-size:17px;margin-bottom:6px;color:#fff}.st p{font-size:14.5px}
/* faq */
.faq{max-width:780px}
details{border-top:1px solid var(--line);padding:20px 0}details:last-child{border-bottom:1px solid var(--line)}
summary{cursor:pointer;font:600 18px Sora;list-style:none;display:flex;justify-content:space-between;gap:16px}
summary::-webkit-details-marker{display:none}summary::after{content:"+";font-size:24px;line-height:1;transition:transform .2s}
details[open] summary::after{transform:rotate(45deg)}
details p{margin-top:12px;color:var(--mute);max-width:640px}
/* cta */
.cta{background:var(--l);color:var(--k);padding:96px 0}
.cta h2{font-size:clamp(32px,5.6vw,64px);letter-spacing:-.035em;max-width:860px}
.cta p{margin:18px 0 32px;font-size:18px;max-width:520px;color:#2a3300}
/* footer */
footer{background:var(--k);color:#fff;padding:72px 0 32px}
.ft{display:grid;grid-template-columns:1.6fr repeat(3,1fr);gap:40px}
footer p,footer li,footer a{color:var(--dmute);font-size:14.5px}
footer h4{font-size:14px;margin-bottom:14px}
footer ul{list-style:none;margin:0;padding:0}footer li{padding:5px 0}footer a:hover{color:var(--l)}
.fb{margin-top:48px;padding-top:24px;border-top:1px solid var(--dline);display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;font-size:13.5px;color:var(--dmute)}
.big{font:700 clamp(40px,12vw,150px)/1 Sora;letter-spacing:-.05em;color:#161618;margin-top:40px;white-space:nowrap;overflow:hidden}
/* tablet */
@media(max-width:1020px){
.hero .wrap{grid-template-columns:1fr}.hub{max-width:560px}
.fw{grid-template-columns:1fr}.arr{transform:rotate(90deg);justify-self:center}
.flow{flex-direction:column;gap:20px;max-width:600px}
.nd{display:grid;grid-template-columns:1fr 1fr;gap:4px 14px;align-items:center}.nd small{grid-column:span 2;margin:0}.nd span{margin:0;text-align:right}
.nd::after{left:24px;top:100%;width:2px;height:20px}
.jr{grid-template-columns:1fr;gap:22px}.st{display:grid;grid-template-columns:38px 1fr;column-gap:16px;padding:0}.st .dot{grid-row:span 2;margin:0}.st::after{display:none}.st h4{margin-top:2px}
.ft{grid-template-columns:1fr 1fr}}
@media(max-width:860px){nav ul{display:none}.cards{grid-template-columns:1fr}}
/* mobile */
@media(max-width:600px){
section{padding:64px 0}.wrap{padding:0 20px}
.hub{gap:12px}.hub .t{padding:18px 14px}.hub .t p{font-size:12.5px}
.nd{display:block}.nd span{text-align:left;margin-top:5px}.flow{padding:18px}
.ctas .btn{width:100%;justify-content:center}.ft{grid-template-columns:1fr}.ic .bd{padding:20px 8px 8px}}
@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}
